(5980867, 874759, 113419, '<td valign="top">good job!  this reminds me of that tv commerical...."look at your man; back at me; at him; now back at me"  lol  although I can''t remember what that commerical is for</td>', 'good job!  this reminds me of that tv commerical...."look at your man; back at me; at him; now back at me"  lol  although I can''t remember what that commerical is for', '2010-04-30 10:37:12.000000', NULL, 1),
(5980904, 874740, 113419, '<td valign="top">beautiful blue eyes!  a great job on this photo - my only suggestion is she needed a very small earring a the whole in the ear lobe causes a slight distraction</td>', 'beautiful blue eyes!  a great job on this photo - my only suggestion is she needed a very small earring a the whole in the ear lobe causes a slight distraction', '2010-04-30 11:22:38.000000', NULL, 1),
(5980951, 871792, 811, '<td valign="top">Overall, I like this shot.  However, to me it feels like it was either shot while she was horizontal and flipped 90* or she is holding on tight to a tree that is leaning "forward."  I just feel like she is about to fall forward on her face.</td>', 'Overall, I like this shot.  However, to me it feels like it was either shot while she was horizontal and flipped 90* or she is holding on tight to a tree that is leaning "forward."  I just feel like she is about to fall forward on her face.', '2010-04-30 12:19:39.000000', NULL, 1),
(5980956, 874889, 811, '<td valign="top">I like how the subject is almost exactly the opposite of the image in the picture.</td>', 'I like how the subject is almost exactly the opposite of the image in the picture.', '2010-04-30 12:23:02.000000', NULL, 1),
(5980961, 874632, 811, '<td valign="top">The color of her skin, especially her legs, looks a bit odd to me.</td>', 'The color of her skin, especially her legs, looks a bit odd to me.', '2010-04-30 12:32:33.000000', NULL, 1),
