(5989906, 874358, 116499, '<td valign="top">This image has great color, focus, and light. While she''s well-styled, there are almost too many competing textures and colors. I think that the sunburst is a little over the top. The reflection in her sunglasses is very nice.</td>', 'This image has great color, focus, and light. While she''s well-styled, there are almost too many competing textures and colors. I think that the sunburst is a little over the top. The reflection in her sunglasses is very nice.', '2010-05-04 19:14:02.000000', NULL, 1),
(5989913, 874173, 116366, '<td valign="top"><strike></strike></td>', '', '2010-05-04 19:17:00.000000', NULL, 1),
(5989917, 874728, 116499, '<td valign="top">This is well-lit and looks like an ad you might see in a magazine. I would have moved the leather pillow slightly to have "GUESS" completely mirrored. The image might have been stronger with a different bracelet/item of jewelry that was more of a "statement" piece: there''s a lot to look at here, and I have trouble figuring out which piece of the bracelet I''m supposed to focus on; however, I recognize this is completely subjective criticism.</td>', 'This is well-lit and looks like an ad you might see in a magazine. I would have moved the leather pillow slightly to have "GUESS" completely mirrored. The image might have been stronger with a different bracelet/item of jewelry that was more of a "statement" piece: there''s a lot to look at here, and I have trouble figuring out which piece of the bracelet I''m supposed to focus on; however, I recognize this is completely subjective criticism.', '2010-05-04 19:18:27.000000', NULL, 1),
(5989921, 874985, 116499, '<td valign="top">I like the lighting in this image a lot; the composition and the expression on the model''s face are also strong. Her pose is distracting, though, from the product (the shoes): perhaps if she had both arms back against the wall or her brought left arm down some this would be stronger.</td>', 'I like the lighting in this image a lot; the composition and the expression on the model''s face are also strong. Her pose is distracting, though, from the product (the shoes): perhaps if she had both arms back against the wall or her brought left arm down some this would be stronger.', '2010-05-04 19:22:37.000000', NULL, 1),
(5989926, 872953, 116499, '<td valign="top">I rated this pretty well, but the message needs to be clearer. He certainly doesn''t look late to me.</td>', 'I rated this pretty well, but the message needs to be clearer. He certainly doesn''t look late to me.', '2010-05-04 19:26:14.000000', NULL, 1),
(5989927, 874173, 116499, '<td valign="top">The back-lighting of this image is great. The image would be stronger if more of the mask were visible.</td>', 'The back-lighting of this image is great. The image would be stronger if more of the mask were visible.', '2010-05-04 19:26:21.000000', NULL, 1),
(5989928, 875133, 116499, '<td valign="top">Is the focus of this image the color/tie or the watch? I like this photo, but I really thought it was about the watch until I saw the title. The message needs to be clearer. Also, you might have considered not cutting off his eyes OR cutting his eyes out completely: it''s strange to see half of his eyes. The dramatic lighting is well-done, and the use of color in this image is really good.</td>', 'Is the focus of this image the color/tie or the watch? I like this photo, but I really thought it was about the watch until I saw the title. The message needs to be clearer. Also, you might have considered not cutting off his eyes OR cutting his eyes out completely: it''s strange to see half of his eyes. The dramatic lighting is well-done, and the use of color in this image is really good.', '2010-05-04 19:26:31.000000', NULL, 1),
(5990141, 874740, 98132, '<td valign="top">This is a beautiful portrait shot! The make-up is high-class and very subtle at the same time. Good luck with this one!</td>', 'This is a beautiful portrait shot! The make-up is high-class and very subtle at the same time. Good luck with this one!', '2010-05-04 21:49:45.000000', NULL, 1),
(5990162, 874774, 61961, '<td valign="top">I think I can guess the photographer, but I often guess wrong, so I''ll just say great job and leave my only sure "10" in the challenge.</td>', 'I think I can guess the photographer, but I often guess wrong, so I''ll just say great job and leave my only sure "10" in the challenge.', '2010-05-04 21:57:33.000000', NULL, 1),
(5990163, 875220, 61961, '<td valign="top">Gorgeous light and very good work from your pretty, young model.  Nice "youth" fashion as well.</td>', 'Gorgeous light and very good work from your pretty, young model.  Nice "youth" fashion as well.', '2010-05-04 21:58:13.000000', NULL, 1),
(5990165, 872521, 61961, '<td valign="top">So bright and clear, and could easily be found in a magazine (and hopefully on the ribbon winner page).  Cheers!</td>', 'So bright and clear, and could easily be found in a magazine (and hopefully on the ribbon winner page).  Cheers!', '2010-05-04 21:59:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5990179, 872953, 61961, '<td valign="top">I can''t which of my teammates took this photo, but it''s fantastic.  I''m sorry I can''t vote on it!  I hope you rock the challenge.</td>', 'I can''t which of my teammates took this photo, but it''s fantastic.  I''m sorry I can''t vote on it!  I hope you rock the challenge.', '2010-05-04 22:02:51.000000', NULL, 1),
(5990185, 874747, 61961, '<td valign="top">I love the sharpness and processing around the eye -- it''s beautiful.  I hope this year to learn more about processing techniques.  Far, far fewer pet photos in this challenge than I expected (two?), and this one is superior.  Best of luck,</td>', 'I love the sharpness and processing around the eye -- it''s beautiful.  I hope this year to learn more about processing techniques.  Far, far fewer pet photos in this challenge than I expected (two?), and this one is superior.  Best of luck,', '2010-05-04 22:05:02.000000', NULL, 1),
(5990191, 875130, 61961, '<td valign="top">Great smile on the model and I like the western-wear.  In my opinion the brick fits with the concept, though the slab maybe could have been re-thought.  Overall I think the slight fuzziness hurts the entry more than anything.</td>', 'Great smile on the model and I like the western-wear.  In my opinion the brick fits with the concept, though the slab maybe could have been re-thought.  Overall I think the slight fuzziness hurts the entry more than anything.', '2010-05-04 22:07:39.000000', NULL, 1),
(5990221, 875199, 57378, '<td valign="top">Interesting lighting but maybe a tad bland - Maybe a hand up at the necklace or something could have added some more interest?</td>', 'Interesting lighting but maybe a tad bland - Maybe a hand up at the necklace or something could have added some more interest?', '2010-05-04 22:17:57.000000', NULL, 1),
(5990222, 874571, 57378, '<td valign="top">Nice lighting and bright colours - Interesting take on the theme which I don''t mind</td>', 'Nice lighting and bright colours - Interesting take on the theme which I don''t mind', '2010-05-04 22:18:28.000000', NULL, 1),
(5990224, 874923, 57378, '<td valign="top">Nice lighting but maybe a tad over lit? I would have loved to have seen a little more room around the model as the background looks very intersting too.</td>', 'Nice lighting but maybe a tad over lit? I would have loved to have seen a little more room around the model as the background looks very intersting too.', '2010-05-04 22:19:50.000000', NULL, 1),
(5990226, 875028, 57378, '<td valign="top">Nice movement but the fan is very distracting as too is the pose</td>', 'Nice movement but the fan is very distracting as too is the pose', '2010-05-04 22:20:18.000000', NULL, 1),
(5990229, 875066, 57378, '<td valign="top">Nice soft lighting and I like the background red - Not a fan of the borders though.</td>', 'Nice soft lighting and I like the background red - Not a fan of the borders though.', '2010-05-04 22:20:53.000000', NULL, 1),
(5990235, 873541, 57378, '<td valign="top">Nice DOF but the lighting is a little harsh and not very atmospheric.</td>', 'Nice DOF but the lighting is a little harsh and not very atmospheric.', '2010-05-04 22:21:31.000000', NULL, 1),
(5990238, 874668, 57378, '<td valign="top">Nice details - Just seems a tad boring with that expression and pose - Also the hot spots from the lights either side are distracting.</td>', 'Nice details - Just seems a tad boring with that expression and pose - Also the hot spots from the lights either side are distracting.', '2010-05-04 22:22:20.000000', NULL, 1),
(5990240, 872346, 57378, '<td valign="top">Great use of the backdrop - The lighting seems a tad harsh though for this kind of shot - Also the shadows block her feet so it looks like she has none which is a little distracting</td>', 'Great use of the backdrop - The lighting seems a tad harsh though for this kind of shot - Also the shadows block her feet so it looks like she has none which is a little distracting', '2010-05-04 22:23:15.000000', NULL, 1),
(5990243, 873705, 57378, '<td valign="top">Nice colours but for a still life it needs to be pin sharp and this has movement which is distracting to the eye</td>', 'Nice colours but for a still life it needs to be pin sharp and this has movement which is distracting to the eye', '2010-05-04 22:23:54.000000', NULL, 1),
(5990246, 874959, 57378, '<td valign="top">Nice funny pic - Like the feel to this</td>', 'Nice funny pic - Like the feel to this', '2010-05-04 22:24:27.000000', NULL, 1),
(5990247, 875138, 57378, '<td valign="top">Nice lighting but the background is a little distracting - Also the model looks a little stiff and awkward.</td>', 'Nice lighting but the background is a little distracting - Also the model looks a little stiff and awkward.', '2010-05-04 22:25:16.000000', NULL, 1),
(5990249, 874720, 57378, '<td valign="top">Nice lighting - Just looks overall a little muddy though.</td>', 'Nice lighting - Just looks overall a little muddy though.', '2010-05-04 22:25:43.000000', NULL, 1),
(5990252, 874655, 57378, '<td valign="top">Nice try t something different - Little soft though which is a bit distracting - If it''s going to be out of focus/soft or have movement that is fine but I feel it needs to be more pronounced - I think you were going for a sharper image here though</td>', 'Nice try t something different - Little soft though which is a bit distracting - If it''s going to be out of focus/soft or have movement that is fine but I feel it needs to be more pronounced - I think you were going for a sharper image here though', '2010-05-04 22:27:01.000000', NULL, 1),
(5990254, 875117, 57378, '<td valign="top">Nice light and I love the stripes on the scarf - Just so much white at the top though tends to take my eyes out of the frame and not keep them in</td>', 'Nice light and I love the stripes on the scarf - Just so much white at the top though tends to take my eyes out of the frame and not keep them in', '2010-05-04 22:27:40.000000', NULL, 1),
(5990257, 872953, 57378, '<td valign="top">Nice angle and lighting - Did you crop it afterwards when you saw yourself in the glasses? It seems that way to me? Nice pose though</td>', 'Nice angle and lighting - Did you crop it afterwards when you saw yourself in the glasses? It seems that way to me? Nice pose though', '2010-05-04 22:28:47.000000', NULL, 1),
(5990261, 874976, 57378, '<td valign="top">Love the tones and overexposed look in this - Very nice and the model has done a good job looking interesting and whimsical.</td>', 'Love the tones and overexposed look in this - Very nice and the model has done a good job looking interesting and whimsical.', '2010-05-04 22:29:29.000000', NULL, 1),
(5990262, 874920, 57378, '<td valign="top">Like the tones but the cropping for me is a little awkward and composition a tad boring</td>', 'Like the tones but the cropping for me is a little awkward and composition a tad boring', '2010-05-04 22:30:04.000000', NULL, 1),
(5990264, 875176, 57378, '<td valign="top">Nice lights but could do with a little something extra like someone walking by in a blur or something to add some depth and interest to this.</td>', 'Nice lights but could do with a little something extra like someone walking by in a blur or something to add some depth and interest to this.', '2010-05-04 22:30:50.000000', NULL, 1),
(5990269, 874940, 57378, '<td valign="top">Nice light - Like the yellow colour - Maybe a little more drama in the pose could have added some interest</td>', 'Nice light - Like the yellow colour - Maybe a little more drama in the pose could have added some interest', '2010-05-04 22:31:43.000000', NULL, 1),
